describe('Mark Record as Favourite', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should mark a record as favourite and display the star icon', () => {
    // Verify initial state: no records are displayed
    cy.get('[data-testid="no-records-message"]').should('be.visible');

    // Intercept the API call to fetch records
    cy.intercept('GET', '/api/records').as('getRecords');

    // Wait for the API call to complete
    cy.wait('@getRecords');

    // Verify records are now visible
    cy.get('[data-testid="record-list"]').should('be.visible');

    // Get the first record
    cy.get('[data-testid="record-item"]').first().as('firstRecord');

    // Verify the record has a title and description
    cy.get('[data-testid="record-title"]', { parent: 'firstRecord' }).should('contain', 'Sample Record');
    cy.get('[data-testid="record-description"]', { parent: 'firstRecord' }).should('contain', 'This is a sample record');

    // Click the star icon to mark as favourite
    cy.get('[data-testid="star-icon"]', { parent: 'firstRecord' }).click();

    // Verify the star icon is now visible
    cy.get('[data-testid="star-icon"]', { parent: 'firstRecord' }).should('be.visible');

    // Verify the record is now marked as favourite
    cy.get('[data-testid="favourite-count"]', { parent: 'firstRecord' }).should('contain', '1');

    // Verify the star icon has changed color
    cy.get('[data-testid="star-icon"]', { parent: 'firstRecord' }).should('have.css', 'color', 'green');

    // Verify the record is now in the favourites list
    cy.get('[data-testid="favourites-list"]').should('be.visible');
    cy.get('[data-testid="favourite-item"]', { text: 'Sample Record' }).should('be.visible');

    // Verify the record is still visible in the main list
    cy.get('[data-testid="record-list"]').should('contain', 'Sample Record');
  });

  it('should handle marking multiple records as favourite and display count', () => {
    // Intercept the API call to fetch multiple records
    cy.intercept('GET', '/api/records').as('getMultipleRecords');

    // Wait for the API call to complete
    cy.wait('@getMultipleRecords');

    // Verify multiple records are now visible
    cy.get('[data-testid="record-list"]').should('be.visible');

    // Get the first two records
    cy.get('[data-testid="record-item"]').first().as('firstRecord');
    cy.get('[data-testid="record-item"]').eq(1).as('secondRecord');

    // Verify the first record has a title and description
    cy.get('[data-testid="record-title"]', { parent: 'firstRecord' }).should('contain', 'Sample Record 1');
    cy.get('[data-testid="record-description"]', { parent: 'firstRecord' }).should('contain', 'This is the first sample record');

    // Verify the second record has a title and description
    cy.get('[data-testid="record-title"]', { parent: 'secondRecord' }).should('contain', 'Sample Record 2');
    cy.get('[data-testid="record-description"]', { parent: 'secondRecord' }).should('contain', 'This is the second sample record');

    // Click the star icon on the first record
    cy.get('[data-testid="star-icon"]', { parent: 'firstRecord' }).click();

    // Verify the star icon is now visible and has changed color
    cy.get('[data-testid="star-icon"]', { parent: 'firstRecord' }).should('be.visible');
    cy.get('[data-testid="star-icon"]', { parent: 'firstRecord' }).should('have.css', 'color', 'green');

    // Click the star icon on the second record
    cy.get('[data-testid="star-icon"]', { parent: 'secondRecord' }).click();

    // Verify the star icon is now visible and has changed color
    cy.get('[data-testid="star-icon"]', { parent: 'secondRecord' }).should('be.visible');
    cy.get('[data-testid="star-icon"]', { parent: 'secondRecord' }).should('have.css', 'color', 'green');

    // Verify the favourite count is incremented for both records
    cy.get('[data-testid="favourite-count"]', { parent: 'firstRecord' }).should('contain', '2');
    cy.get('[data-testid="favourite-count"]', { parent: 'secondRecord' }).should('contain', '2');

    // Verify the star icon is now visible for both records
    cy.get('[data-testid="star-icon"]', { parent: 'firstRecord' }).should('be.visible');
    cy.get('[data-testid="star-icon"]', { parent: 'secondRecord' }).should('be.visible');

    // Verify the records are still visible in the main list
    cy.get('[data-testid="record-list"]').should('contain', 'Sample Record 1');
    cy.get('[data-testid="record-list"]').should('contain', 'Sample Record 2');
  });
});
